package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.application.AiGovernanceService;import com.yuegang.zhihui.ai.domain.ModelGateway;public final class GovernedModelGateway implements ModelGateway{private final ModelGateway delegate;private final AiGovernanceService governance;public GovernedModelGateway(ModelGateway d,AiGovernanceService g){delegate=d;governance=g;}public String answer(String ignored,String user){return delegate.answer(governance.activeSystemPrompt(),user);}public String modelName(){return delegate.modelName();}public boolean available(){return delegate.available();}}
